#include <sstream>
#include <vector>
using namespace std;

class Solution {
public:
    bool areSentencesSimilar(string s1, string s2) {
        vector<string> a = split(s1), b = split(s2);
        if (a.size() > b.size()) swap(a, b);
        int i = 0;
        while (i < a.size() && a[i] == b[i]) ++i;
        int j = 0;
        while (j < a.size() - i && a[a.size() - 1 - j] == b[b.size() - 1 - j]) ++j;
        return i + j == a.size();
    }

    vector<string> split(string& s) {
        istringstream iss(s);
        string word;
        vector<string> res;
        while (iss >> word) res.push_back(word);
        return res;
    }
};
